import { ThemeProvider } from '@/components/ui/theme-provider'
import { ConfigProvider, type ConfigProviderProps } from '@/components/ui/config-provider'
import { TooltipProvider } from '@/components/ui/tooltip'
import { Toaster } from '@/components/ui/sonner'
import * as React from 'react'
import { useMessage } from '@/components/ui/message'
import { useConfirm } from '@/components/ui/confirm'
const AppContext = React.createContext<{
  message: ReturnType<typeof useMessage>[0]
  confirm: ReturnType<typeof useConfirm>[0]
} | null>(null)
export function useApp() {
  const context = React.useContext(AppContext)
  if (!context) throw new Error('useApp requires AppProvider')
  return context
}
function AppServices({ children }: { children: React.ReactNode }) {
  const [message, holder] = useMessage(),
    [confirm, modal] = useConfirm()
  return (
    <AppContext.Provider value={{ message, confirm }}>
      {children}
      {holder}
      {modal}
    </AppContext.Provider>
  )
}
export function AppProvider({ children, ...props }: ConfigProviderProps) {
  return (
    <ThemeProvider attribute="class" defaultTheme="system" enableSystem>
      <ConfigProvider {...props}>
        <TooltipProvider>
          <AppServices>{children}</AppServices>
          <Toaster richColors closeButton />
        </TooltipProvider>
      </ConfigProvider>
    </ThemeProvider>
  )
}

import * as React from 'react'
export type Theme = 'light' | 'dark' | 'system'
const ThemeContext = React.createContext<{
  theme: Theme
  resolvedTheme: 'light' | 'dark'
  setTheme: (theme: string) => void
}>({ theme: 'light', resolvedTheme: 'light', setTheme: () => {} })
export function ThemeProvider({
  children,
  defaultTheme = 'system',
}: {
  children: React.ReactNode
  defaultTheme?: Theme
  attribute?: 'class'
  enableSystem?: boolean
}) {
  const [theme, setTheme] = React.useState<Theme>(() => {
    try {
      const saved = localStorage.getItem('ergon-appearance')
      return saved === 'light' || saved === 'dark' || saved === 'system' ? saved : defaultTheme
    } catch {
      return defaultTheme
    }
  })
  const [system, setSystem] = React.useState<'light' | 'dark'>(() =>
    window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light',
  )
  React.useEffect(() => {
    const media = window.matchMedia('(prefers-color-scheme: dark)')
    const listener = () => setSystem(media.matches ? 'dark' : 'light')
    media.addEventListener('change', listener)
    return () => media.removeEventListener('change', listener)
  }, [])
  const resolvedTheme = theme === 'system' ? system : theme
  React.useLayoutEffect(() => {
    document.documentElement.classList.toggle('dark', resolvedTheme === 'dark')
    document.documentElement.style.colorScheme = resolvedTheme
    localStorage.setItem('ergon-appearance', theme)
  }, [theme, resolvedTheme])
  return (
    <ThemeContext.Provider
      value={{
        theme,
        resolvedTheme,
        setTheme: (next) => {
          if (next === 'light' || next === 'dark' || next === 'system') setTheme(next)
        },
      }}
    >
      {children}
    </ThemeContext.Provider>
  )
}
export function useTheme() {
  return React.useContext(ThemeContext)
}

import { contrastForeground } from '@/lib/contrast'
import * as React from 'react'
import { cn } from '@/lib/utils'
import { Direction } from 'radix-ui'
export interface UIConfig {
  density: 'comfortable' | 'compact'
  direction: 'ltr' | 'rtl'
  locale: string
}
const ConfigContext = React.createContext<UIConfig>({
  density: 'comfortable',
  direction: 'ltr',
  locale: 'en-US',
})
const PortalContext = React.createContext<HTMLElement | null>(null)
export const usePortalContainer = () => React.useContext(PortalContext) ?? undefined
export const useUIConfig = () => React.useContext(ConfigContext)
export interface ConfigProviderProps extends React.HTMLAttributes<HTMLDivElement> {
  density?: UIConfig['density']
  direction?: UIConfig['direction']
  locale?: string
  accent?: string
  radius?: number
}
export function ConfigProvider({
  density: providedDensity,
  direction: providedDirection,
  locale: providedLocale,
  accent,
  radius,
  children,
  style,
  className,
  ...props
}: ConfigProviderProps) {
  const parent = useUIConfig(),
    density = providedDensity ?? parent.density,
    direction = providedDirection ?? parent.direction,
    locale = providedLocale ?? parent.locale
  const [portal, setPortal] = React.useState<HTMLDivElement | null>(null)
  return (
    <ConfigContext.Provider value={{ density, direction, locale }}>
      <PortalContext.Provider value={portal}>
        <Direction.Provider dir={direction}>
          <div
            dir={direction}
            lang={locale}
            data-density={density}
            className={cn('ergon-root', className)}
            style={
              {
                ...(accent
                  ? {
                      '--primary': accent,
                      '--ring': accent,
                      '--primary-foreground': contrastForeground(accent),
                    }
                  : {}),
                ...(radius !== undefined ? { '--radius': `${radius}px` } : {}),
                ...style,
              } as React.CSSProperties
            }
            {...props}
          >
            {children}
            <div ref={setPortal} data-ergon-portals="" style={{ display: 'contents' }} />
          </div>
        </Direction.Provider>
      </PortalContext.Provider>
    </ConfigContext.Provider>
  )
}

